begin;

on conflict (id) do update set handle=excluded.handle, display_name=excluded.display_name, reputation=excluded.reputation;

-- SEED IMAGE INTEGRITY INVARIANT:
-- A VERIFIED or AWAITING work must never use a photo of a screen, a stock UI
-- screenshot, or an image whose subject differs from its stated category,
-- title, and description. Screen captures are valid only when the work itself
-- is screen-based and the description explicitly says so.
-- Never rewrite work text to excuse an unrelated image: swap the image or
-- delete the record.

on conflict (id) do update set title=excluded.title, description=excluded.description, category=excluded.category, aspect_ratio=excluded.aspect_ratio, image_url=excluded.image_url, thumb_url=excluded.thumb_url, origin_input=excluded.origin_input, status=excluded.status, proof_count=excluded.proof_count, published_at=excluded.published_at;

on conflict (work_id,seq) do update set captured_at=excluded.captured_at,title=excluded.title,body=excluded.body,thumb_url=excluded.thumb_url;

on conflict (work_id) do update set capture_device=excluded.capture_device,lens=excluded.lens,iso=excluded.iso,shutter=excluded.shutter,dimensions=excluded.dimensions,file_format=excluded.file_format,original_hash=excluded.original_hash,captured_at=excluded.captured_at,uploaded_at=excluded.uploaded_at;

on conflict (id) do update set name=excluded.name,sentence=excluded.sentence,hedge=excluded.hedge,confidence=excluded.confidence;

do $$
declare
  owner_uuid uuid;
begin
  select id into owner_uuid from auth.users order by created_at asc limit 1;
  if owner_uuid is null then owner_uuid := '774d4f36-9acf-5ccc-b01d-7121c18f36d8'::uuid; end if;
  values(owner_uuid, ('member_' || substr(owner_uuid::text,1,8))::citext, 'Humn member')
  on conflict(id) do nothing;
end $$;


commit;
